/**
 * The one service worker the app registers (a scope can only have one).
 *  - production: /worker.js, generated by `npm run cache` (workbox-config.js). It caches static files and imports
 *    /service-worker.js, so push notifications keep working.
 *  - development: /service-worker.js only (push, no caching). worker.js is a build artefact and may be missing or stale.
 * Everything that registers a worker goes through registerAppServiceWorker(); two different scripts for the same scope would
 * keep replacing each other.
 */
const PUSH_WORKER_URL = "/service-worker.js";
export const SERVICE_WORKER_URL = process.env.NODE_ENV === "production" ? "/worker.js" : PUSH_WORKER_URL;

export async function registerAppServiceWorker(): Promise<ServiceWorkerRegistration> {
  if (SERVICE_WORKER_URL === PUSH_WORKER_URL) return navigator.serviceWorker.register(PUSH_WORKER_URL);
  try {
    return await navigator.serviceWorker.register(SERVICE_WORKER_URL);
  } catch {
    // A deploy that did not generate worker.js must not lose push notifications.
    return navigator.serviceWorker.register(PUSH_WORKER_URL);
  }
}
